SELECT (DATE_TRUNC('DAY', "SCHEDULED_AT")) AS "TIME_BUCKET", (CAST(CASE WHEN (COUNT(*)) = 0 OR (COUNT(*)) IS NULL THEN NULL ELSE CAST((SUM(CASE WHEN STATE = 'SUCCEEDED' THEN 1 ELSE 0 END)) AS DECIMAL(38, 15)) / CAST((COUNT(*)) AS DECIMAL(38, 15)) END AS DECIMAL(38, 15))) AS "PIPE_TASK_SUCCESS_RATE" FROM (SELECT "NAME" AS TASK_NAME, "DATABASE_NAME" AS DATABASE_NAME, "SCHEMA_NAME" AS SCHEMA_NAME, "STATE" AS STATE, "ERROR_CODE" AS ERROR_CODE, "QUERY_ID" AS QUERY_ID, "GRAPH_ROOT_TASK_ID" AS GRAPH_ROOT_TASK_ID, "GRAPH_RUN_GROUP_ID" AS GRAPH_RUN_GROUP_ID, "RUN_ID" AS RUN_ID, (TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME")) AS SCHEDULED_AT, (TRY_TO_TIMESTAMP_NTZ("QUERY_START_TIME")) AS STARTED_AT, (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")) AS COMPLETED_AT, (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME")), (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")))) AS DURATION_SEC, PERCENT_RANK() OVER (PARTITION BY "NAME", (NULL) ORDER BY (DATEDIFF(SECOND, (TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME")), (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME"))))) AS DURATION_PERCENT_RANK, SUM(CASE WHEN "STATE" = 'FAILED' THEN 1 ELSE 0 END) OVER (PARTITION BY "NAME", (NULL)) AS TASK_FAILURE_COUNT, MAX(CASE WHEN "STATE" = 'SUCCEEDED' THEN (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")) END) OVER (PARTITION BY "NAME", (NULL)) AS LAST_SUCCESS_AT, MAX((TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME"))) OVER (PARTITION BY (NULL)) AS OBSERVED_THROUGH_AT, (DATEDIFF(SECOND, MAX(CASE WHEN "STATE" = 'SUCCEEDED' THEN (TRY_TO_TIMESTAMP_NTZ("COMPLETED_TIME")) END) OVER (PARTITION BY "NAME", (NULL)), MAX((TRY_TO_TIMESTAMP_NTZ("SCHEDULED_TIME"))) OVER (PARTITION BY (NULL)))) AS SECONDS_SINCE_LAST_SUCCESS, (NULL) AS ACCOUNT_NAME /* The account these rows came from (see the ACCOUNT_OF shim). */ FROM task_history) AS base GROUP BY (DATE_TRUNC('DAY', "SCHEDULED_AT")) ORDER BY "PIPE_TASK_SUCCESS_RATE" DESC NULLS LAST, "TIME_BUCKET" LIMIT 100
